--
-- Table structure for table `moves`
--

DROP TABLE IF EXISTS `moves`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `moves` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `type_id` int unsigned NOT NULL,
  `name` varchar(50) NOT NULL,
  `effect` text NOT NULL,
  `attack_type` varchar(15) NOT NULL,
  `damage` tinyint unsigned DEFAULT NULL,
  `accuracy` tinyint unsigned NOT NULL,
  `mt` tinyint unsigned DEFAULT NULL,
  `mn` tinyint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `moves_name_unique` (`name`),
  KEY `moves_damage_index` (`damage`),
  KEY `moves_mt_index` (`mt`),
  KEY `moves_mn_index` (`mn`),
  KEY `moves_type_id_foreign` (`type_id`),
  CONSTRAINT `moves_type_id_foreign` FOREIGN KEY (`type_id`) REFERENCES `types` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=165 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

