INSERT INTO `pokemon` VALUES (1,'Bulbasaur',0.7,6.9,1,1,'A strange seed was planted on its back at birth. The plant sprouts and grows with this POKéMON.',87.50,12.50,'bulbasaur.png'),(2,'Ivysaur',1,13,2,1,'When the bulb on its back grows large, it appears to lose the ability to stand on its hind legs.',87.50,12.50,'ivysaur.png'),(3,'Venusaur',2,100,3,1,'The plant blooms when it is absorbing solar energy. It stays on the move to seek sunlight.',87.50,12.50,'venusaur.png'),(4,'Charmander',0.6,8.5,4,1,'Obviously prefers hot places. When it rains, steam is said to spout from the tip of its tail.',87.50,12.50,'charmander.png'),(5,'Charmeleon',1.1,19,5,1,'When it swings its burning tail, it elevates the temperature to unbearably high levels.',87.50,12.50,'charmeleon.png'),(6,'Charizard',1.7,90.5,6,1,'Spits fire that is hot enough to melt boulders. Known to cause forest fires unintentionally.',87.50,12.50,'charizard.png'),(7,'Squirtle',0.5,9,7,1,'After birth, its back swells and hardens into a shell. Powerfully sprays foam from its mouth.',87.50,12.50,'squirtle.png'),(8,'Wartortle',1,22.5,8,1,'Often hides in water to stalk unwary prey. For swimming fast, it moves its ears to maintain balance.',87.50,12.50,'wartortle.png'),(9,'Blastoise',1.6,85.5,9,1,'A brutal POKéMON with pressurized water jets on its shell. They are used for high speed tackles.',87.50,12.50,'blastoise.png'),(10,'Caterpie',0.3,2.9,10,1,'Its short feet are tipped with suction pads that enable it to tirelessly climb slopes and walls.',50.00,50.00,'caterpie.png'),(11,'Metapod',0.7,9.9,11,1,'This POKéMON is vulnerable to attack while its shell is soft, exposing its weak and tender body.',50.00,50.00,'metapod.png'),(12,'Butterfree',1.1,32,12,1,'In battle, it flaps its wings at high speed to release highly toxic dust into the air.',50.00,50.00,'butterfree.png'),(13,'Weedle',0.3,3.2,13,1,'Often found in forests, eating leaves. It has a sharp venomous stinger on its head.',50.00,50.00,'weedle.png'),(14,'Kakuna',0.6,10,14,1,'Almost incapable of moving, this POKéMON can only harden its shell to protect itself from predators.',50.00,50.00,'kakuna.png'),(15,'Beedrill',1,29.5,15,1,'Flies at high speed and attacks using its large venomous stingers on its forelegs and tail.',50.00,50.00,'beedrill.png'),(16,'Pidgey',0.3,1.8,16,1,'A common sight in forests and woods. It flaps its wings at ground level to kick up blinding sand.',50.00,50.00,'pidgey.png'),(17,'Pidgeotto',1.1,30,17,1,'Very protective of its sprawling territorial area, this POKéMON will fiercely peck at any intruder.',50.00,50.00,'pidgeotto.png'),(18,'Pidgeot',1.5,39.5,18,1,'When hunting, it skims the surface of water at high speed to pick off unwary prey such as MAGIKARP.',50.00,50.00,'pidgeot.png'),(19,'Rattata',0.3,3.5,19,1,'Bites anything when it attacks. Small and very quick, it is a common sight in many places.',50.00,50.00,'rattata.png'),(20,'Raticate',0.7,18.5,20,1,'It uses its whis­ kers to maintain its balance. It apparently slows down if they are cut off.',50.00,50.00,'raticate.png'),(21,'Spearow',0.3,2,21,1,'Eats bugs in grassy areas. It has to flap its short wings at high speed to stay airborne.',50.00,50.00,'spearow.png'),(22,'Fearow',1.2,38,22,1,'With its huge and magnificent wings, it can keep aloft without ever having to land for rest.',50.00,50.00,'fearow.png'),(23,'Ekans',2,6.9,23,1,'Moves silently and stealthily. Eats the eggs of birds, such as PIDGEY and SPEAROW, whole.',50.00,50.00,'ekans.png'),(24,'Arbok',3.5,65,24,1,'It is rumored that the ferocious warning markings on its belly differ from area to area.',50.00,50.00,'arbok.png'),(25,'Pikachu',0.4,6,25,1,'When several of these POKéMON gather, their electricity could build and cause lightning storms.',50.00,50.00,'pikachu.png'),(26,'Raichu',0.8,30,26,1,'Its long tail serves as a ground to protect itself from its own high voltage power.',50.00,50.00,'raichu.png'),(27,'Sandshrew',0.6,12,27,1,'Burrows deep underground in arid locations far from water. It only emerges to hunt for food.',50.00,50.00,'sandshrew.png'),(28,'Sandslash',1,29.5,28,1,'Curls up into a spiny ball when threatened. It can roll while curled up to attack or escape.',50.00,50.00,'sandslash.png'),(29,'Nidoran-f',0.4,7,29,1,'Although small, its venomous barbs render this POKéMON dangerous. The female has smaller horns.',0.00,100.00,'nidoran-f.png'),(30,'Nidorina',0.8,20,30,1,'The female\'s horn develops slowly. Prefers physical attacks such as clawing and biting.',0.00,100.00,'nidorina.png'),(31,'Nidoqueen',1.3,60,31,1,'Its hard scales provide strong protection. It uses its hefty bulk to execute powerful moves.',0.00,100.00,'nidoqueen.png'),(32,'Nidoran-m',0.5,9,32,1,'Stiffens its ears to sense danger. The larger its horns, the more powerful its secreted venom.',100.00,0.00,'nidoran-m.png'),(33,'Nidorino',0.9,19.5,33,1,'An aggressive POKéMON that is quick to attack. The horn on its head secretes a powerful venom.',100.00,0.00,'nidorino.png'),(34,'Nidoking',1.4,62,34,1,'It uses its powerful tail in battle to smash, constrict, then break the prey\'s bones.',100.00,0.00,'nidoking.png'),(35,'Clefairy',0.6,7.5,35,1,'Its magical and cute appeal has many admirers. It is rare and found only in certain areas.',25.00,75.00,'clefairy.png'),(36,'Clefable',1.3,40,36,1,'A timid fairy POKéMON that is rarely seen. It will run and hide the moment it senses people.',25.00,75.00,'clefable.png'),(37,'Vulpix',0.6,9.9,37,1,'At the time of birth, it has just one tail. The tail splits from its tip as it grows older.',25.00,75.00,'vulpix.png'),(38,'Ninetales',1.1,19.9,38,1,'Very smart and very vengeful. Grabbing one of its many tails could result in a 1000-year curse.',25.00,75.00,'ninetales.png'),(39,'Jigglypuff',0.5,5.5,39,1,'When its huge eyes light up, it sings a mysteriously soothing melody that lulls its enemies to sleep.',25.00,75.00,'jigglypuff.png'),(40,'Wigglytuff',1,12,40,1,'The body is soft and rubbery. When angered, it will suck in air and inflate itself to an enormous size.',25.00,75.00,'wigglytuff.png'),(41,'Zubat',0.8,7.5,41,1,'Forms colonies in perpetually dark places. Uses ultrasonic waves to identify and approach targets.',50.00,50.00,'zubat.png'),(42,'Golbat',1.6,55,42,1,'Once it strikes, it will not stop draining energy from the victim even if it gets too heavy to fly.',50.00,50.00,'golbat.png'),(43,'Oddish',0.5,5.4,43,1,'During the day, it keeps its face buried in the ground. At night, it wanders around sowing its seeds.',50.00,50.00,'oddish.png'),(44,'Gloom',0.8,8.6,44,1,'The fluid that oozes from its mouth isn\'t drool. It is a nectar that is used to attract prey.',50.00,50.00,'gloom.png'),(45,'Vileplume',1.2,18.6,45,1,'The larger its petals, the more toxic pollen it contains. Its big head is heavy and hard to hold up.',50.00,50.00,'vileplume.png'),(46,'Paras',0.3,5.4,46,1,'Burrows to suck tree roots. The mushrooms on its back grow by draw­ ing nutrients from the bug host.',50.00,50.00,'paras.png'),(47,'Parasect',1,29.5,47,1,'A host-parasite pair in which the parasite mushroom has taken over the host bug. Prefers damp places.',50.00,50.00,'parasect.png'),(48,'Venonat',1,30,48,1,'Lives in the shadows of tall trees where it eats insects. It is attracted by light at night.',50.00,50.00,'venonat.png'),(49,'Venomoth',1.5,12.5,49,1,'The dust-like scales covering its wings are color coded to indicate the kinds of poison it has.',50.00,50.00,'venomoth.png'),(50,'Diglett',0.2,0.8,50,1,'Lives about one yard underground where it feeds on plant roots. It sometimes appears above ground.',50.00,50.00,'diglett.png'),(51,'Dugtrio',0.7,33.3,51,1,'A team of DIGLETT triplets. It triggers huge earthquakes by burrowing 60 miles underground.',50.00,50.00,'dugtrio.png'),(52,'Meowth',0.4,4.2,52,1,'Adores circular objects. Wanders the streets on a nightly basis to look for dropped loose change.',50.00,50.00,'meowth.png'),(53,'Persian',1,32,53,1,'Although its fur has many admirers, it is tough to raise as a pet because of its fickle meanness.',50.00,50.00,'persian.png'),(54,'Psyduck',0.8,19.6,54,1,'While lulling its enemies with its vacant look, this wily POKéMON will use psychokinetic powers.',50.00,50.00,'psyduck.png'),(55,'Golduck',1.7,76.6,55,1,'Often seen swim­ ming elegantly by lake shores. It is often mistaken for the Japanese monster, Kappa.',50.00,50.00,'golduck.png'),(56,'Mankey',0.5,28,56,1,'Extremely quick to anger. It could be docile one moment then thrashing away the next instant.',50.00,50.00,'mankey.png'),(57,'Primeape',1,32,57,1,'Always furious and tenacious to boot. It will not abandon chasing its quarry until it is caught.',50.00,50.00,'primeape.png'),(58,'Growlithe',0.7,19,58,1,'Very protective of its territory. It will bark and bite to repel intruders from its space.',75.00,25.00,'growlithe.png'),(59,'Arcanine',1.9,155,59,1,'A POKéMON that has been admired since the past for its beauty. It runs agilely as if on wings.',75.00,25.00,'arcanine.png'),(60,'Poliwag',0.6,12.4,60,1,'Its newly grown legs prevent it from running. It appears to prefer swimming than trying to stand.',50.00,50.00,'poliwag.png'),(61,'Poliwhirl',1,20,61,1,'Capable of living in or out of water. When out of water, it sweats to keep its body slimy.',50.00,50.00,'poliwhirl.png'),(62,'Poliwrath',1.3,54,62,1,'An adept swimmer at both the front crawl and breast stroke. Easily overtakes the best human swimmers.',50.00,50.00,'poliwrath.png'),(63,'Abra',0.9,19.5,63,1,'Using its ability to read minds, it will identify impending danger and TELEPORT to safety.',75.00,25.00,'abra.png'),(64,'Kadabra',1.3,56.5,64,1,'It emits special alpha waves from its body that induce headaches just by being close by.',75.00,25.00,'kadabra.png'),(65,'Alakazam',1.5,48,65,1,'Its brain can out­ perform a super­ computer. Its intelligence quotient is said to be 5,000.',75.00,25.00,'alakazam.png'),(66,'Machop',0.8,19.5,66,1,'Loves to build its muscles. It trains in all styles of martial arts to become even stronger.',75.00,25.00,'machop.png'),(67,'Machoke',1.5,70.5,67,1,'Its muscular body is so powerful, it must wear a power save belt to be able to regulate its motions.',75.00,25.00,'machoke.png'),(68,'Machamp',1.6,130,68,1,'Using its heavy muscles, it throws powerful punches that can send the victim clear over the horizon.',75.00,25.00,'machamp.png'),(69,'Bellsprout',0.7,4,69,1,'A carnivorous POKéMON that traps and eats bugs. It uses its root feet to soak up needed moisture.',50.00,50.00,'bellsprout.png'),(70,'Weepinbell',1,6.4,70,1,'It spits out POISONPOWDER to immobilize the enemy and then finishes it with a spray of ACID.',50.00,50.00,'weepinbell.png'),(71,'Victreebel',1.7,15.5,71,1,'Said to live in huge colonies deep in jungles, although no one has ever returned from there.',50.00,50.00,'victreebel.png'),(72,'Tentacool',0.9,45.5,72,1,'Drifts in shallow seas. Anglers who hook them by accident are often punished by its stinging acid.',50.00,50.00,'tentacool.png'),(73,'Tentacruel',1.6,55,73,1,'The tentacles are normally kept short. On hunts, they are extended to ensnare and immobilize prey.',50.00,50.00,'tentacruel.png'),(74,'Geodude',0.4,20,74,1,'Found in fields and mountains. Mistaking them for boulders, people often step or trip on them.',50.00,50.00,'geodude.png'),(75,'Graveler',1,105,75,1,'Rolls down slopes to move. It rolls over any obstacle without slowing or changing its direction.',50.00,50.00,'graveler.png'),(76,'Golem',1.4,300,76,1,'Its boulder-like body is extremely hard. It can easily withstand dynamite blasts without damage.',50.00,50.00,'golem.png'),(77,'Ponyta',1,30,77,1,'Its hooves are 10 times harder than diamonds. It can trample anything completely flat in little time.',50.00,50.00,'ponyta.png'),(78,'Rapidash',1.7,95,78,1,'Very competitive, this POKéMON will chase anything that moves fast in the hopes of racing it.',50.00,50.00,'rapidash.png'),(79,'Slowpoke',1.2,36,79,1,'Incredibly slow and dopey. It takes 5 seconds for it to feel pain when under attack.',50.00,50.00,'slowpoke.png'),(80,'Slowbro',1.6,78.5,80,1,'The SHELLDER that is latched onto SLOWPOKE\'s tail is said to feed on the host\'s left over scraps.',50.00,50.00,'slowbro.png'),(81,'Magnemite',0.3,6,81,1,'Uses anti-gravity to stay suspended. Appears without warning and uses THUNDER WAVE and similar moves.',NULL,NULL,'magnemite.png'),(82,'Magneton',1,60,82,1,'Formed by several MAGNEMITEs linked together. They frequently appear when sunspots flare up.',NULL,NULL,'magneton.png'),(83,'Farfetchd',0.8,15,83,1,'The sprig of green onions it holds is its weapon. It is used much like a metal sword.',50.00,50.00,'farfetchd.png'),(84,'Doduo',1.4,39.2,84,1,'A bird that makes up for its poor flying with its fast foot speed. Leaves giant footprints.',50.00,50.00,'doduo.png'),(85,'Dodrio',1.8,85.2,85,1,'Uses its three brains to execute complex plans. While two heads sleep, one head stays awake.',50.00,50.00,'dodrio.png'),(86,'Seel',1.1,90,86,1,'The protruding horn on its head is very hard. It is used for bashing through thick ice.',50.00,50.00,'seel.png'),(87,'Dewgong',1.7,120,87,1,'Stores thermal energy in its body. Swims at a steady 8 knots even in intensely cold waters.',50.00,50.00,'dewgong.png'),(88,'Grimer',0.9,30,88,1,'Appears in filthy areas. Thrives by sucking up polluted sludge that is pumped out of factories.',50.00,50.00,'grimer.png'),(89,'Muk',1.2,30,89,1,'Thickly covered with a filthy, vile sludge. It is so toxic, even its footprints contain poison.',50.00,50.00,'muk.png'),(90,'Shellder',0.3,4,90,1,'Its hard shell repels any kind of attack. It is vulnerable only when its shell is open.',50.00,50.00,'shellder.png'),(91,'Cloyster',1.5,132.5,91,1,'When attacked, it launches its horns in quick volleys. Its innards have never been seen.',50.00,50.00,'cloyster.png'),(92,'Gastly',1.3,0.1,92,1,'Almost invisible, this gaseous POKéMON cloaks the target and puts it to sleep without notice.',50.00,50.00,'gastly.png'),(93,'Haunter',1.6,0.1,93,1,'Because of its ability to slip through block walls, it is said to be from an­ other dimension.',50.00,50.00,'haunter.png'),(94,'Gengar',1.5,40.5,94,1,'Under a full moon, this POKéMON likes to mimic the shadows of people and laugh at their fright.',50.00,50.00,'gengar.png'),(95,'Onix',8.8,210,95,1,'As it grows, the stone portions of its body harden to become similar to a diamond, but colored black.',50.00,50.00,'onix.png'),(96,'Drowzee',1,32.4,96,1,'Puts enemies to sleep then eats their dreams. Occasionally gets sick from eating bad dreams.',50.00,50.00,'drowzee.png'),(97,'Hypno',1.6,75.6,97,1,'When it locks eyes with an enemy, it will use a mix of PSI moves such as HYPNOSIS and CONFUSION.',50.00,50.00,'hypno.png'),(98,'Krabby',0.4,6.5,98,1,'Its pincers are not only powerful weapons, they are used for balance when walking sideways.',50.00,50.00,'krabby.png'),(99,'Kingler',1.3,60,99,1,'The large pincer has 10000 hp of crushing power. However, its huge size makes it unwieldy to use.',50.00,50.00,'kingler.png'),(100,'Voltorb',0.5,10.4,100,1,'Usually found in power plants. Easily mistaken for a POKé BALL, they have zapped many people.',NULL,NULL,'voltorb.png'),(101,'Electrode',1.2,66.6,101,1,'It stores electric energy under very high pressure. It often explodes with little or no provocation.',NULL,NULL,'electrode.png'),(102,'Exeggcute',0.4,2.5,102,1,'Often mistaken for eggs. When disturbed, they quickly gather and attack in swarms.',50.00,50.00,'exeggcute.png'),(103,'Exeggutor',2,120,103,1,'Legend has it that on rare occasions, one of its heads will drop off and continue on as an EXEGGCUTE.',50.00,50.00,'exeggutor.png'),(104,'Cubone',0.4,6.5,104,1,'Because it never removes its skull helmet, no one has ever seen this POKéMON\'s real face.',50.00,50.00,'cubone.png'),(105,'Marowak',1,45,105,1,'The bone it holds is its key weapon. It throws the bone skillfully like a boomerang to KO targets.',50.00,50.00,'marowak.png'),(106,'Hitmonlee',1.5,49.8,106,1,'When in a hurry, its legs lengthen progressively. It runs smoothly with extra long, loping strides.',100.00,0.00,'hitmonlee.png'),(107,'Hitmonchan',1.4,50.2,107,1,'While apparently doing nothing, it fires punches in lightning fast volleys that are impossible to see.',100.00,0.00,'hitmonchan.png'),(108,'Lickitung',1.2,65.5,108,1,'Its tongue can be extended like a chameleon\'s. It leaves a tingling sensation when it licks enemies.',50.00,50.00,'lickitung.png'),(109,'Koffing',0.6,1,109,1,'Because it stores several kinds of toxic gases in its body, it is prone to exploding without warning.',50.00,50.00,'koffing.png'),(110,'Weezing',1.2,9.5,110,1,'Where two kinds of poison gases meet, 2 KOFFINGs can fuse into a WEEZING over many years.',50.00,50.00,'weezing.png'),(111,'Rhyhorn',1,115,111,1,'Its massive bones are 1000 times harder than human bones. It can easily knock a trailer flying.',50.00,50.00,'rhyhorn.png'),(112,'Rhydon',1.9,120,112,1,'Protected by an armor-like hide, it is capable of living in molten lava of 3,600 degrees.',50.00,50.00,'rhydon.png'),(113,'Chansey',1.1,34.6,113,1,'A rare and elusive POKéMON that is said to bring happiness to those who manage to get it.',0.00,100.00,'chansey.png'),(114,'Tangela',1,35,114,1,'The whole body is swathed with wide vines that are similar to sea­ weed. Its vines shake as it walks.',50.00,50.00,'tangela.png'),(115,'Kangaskhan',2.2,80,115,1,'The infant rarely ventures out of its mother\'s protective pouch until it is 3 years old.',0.00,100.00,'kangaskhan.png'),(116,'Horsea',0.4,8,116,1,'Known to shoot down flying bugs with precision blasts of ink from the surface of the water.',50.00,50.00,'horsea.png'),(117,'Seadra',1.2,25,117,1,'Capable of swim­ ming backwards by rapidly flapping its wing-like pectoral fins and stout tail.',50.00,50.00,'seadra.png'),(118,'Goldeen',0.6,15,118,1,'Its tail fin billows like an elegant ballroom dress, giving it the nickname of the Water Queen.',50.00,50.00,'goldeen.png'),(119,'Seaking',1.3,39,119,1,'In the autumn spawning season, they can be seen swimming power­ fully up rivers and creeks.',50.00,50.00,'seaking.png'),(120,'Staryu',0.8,34.5,120,1,'An enigmatic POKéMON that can effortlessly regenerate any appendage it loses in battle.',NULL,NULL,'staryu.png'),(121,'Starmie',1.1,80,121,1,'Its central core glows with the seven colors of the rainbow. Some people value the core as a gem.',NULL,NULL,'starmie.png'),(122,'Mr-mime',1.3,54.5,122,1,'If interrupted while it is miming, it will slap around the offender with its broad hands.',100.00,0.00,'mr-mime.png'),(123,'Scyther',1.5,56,123,1,'With ninja-like agility and speed, it can create the illusion that there is more than one.',50.00,50.00,'scyther.png'),(124,'Jynx',1.4,40.6,124,1,'It seductively wiggles its hips as it walks. It can cause people to dance in unison with it.',0.00,100.00,'jynx.png'),(125,'Electabuzz',1.1,30,125,1,'Normally found near power plants, they can wander away and cause major blackouts in cities.',75.00,25.00,'electabuzz.png'),(126,'Magmar',1.3,44.5,126,1,'Its body always burns with an orange glow that enables it to hide perfectly among flames.',75.00,25.00,'magmar.png'),(127,'Pinsir',1.5,55,127,1,'If it fails to crush the victim in its pincers, it will swing it around and toss it hard.',50.00,50.00,'pinsir.png'),(128,'Tauros',1.4,88.4,128,1,'When it targets an enemy, it charges furiously while whipping its body with its long tails.',100.00,0.00,'tauros.png'),(129,'Magikarp',0.9,10,129,1,'In the distant past, it was somewhat stronger than the horribly weak descendants that exist today.',50.00,50.00,'magikarp.png'),(130,'Gyarados',6.5,235,130,1,'Rarely seen in the wild. Huge and vicious, it is capable of destroying entire cities in a rage.',50.00,50.00,'gyarados.png'),(131,'Lapras',2.5,220,131,1,'A POKéMON that has been over­ hunted almost to extinction. It can ferry people across the water.',50.00,50.00,'lapras.png'),(132,'Ditto',0.3,4,132,1,'Capable of copying an enemy\'s genetic code to instantly transform itself into a duplicate of the enemy.',NULL,NULL,'ditto.png'),(133,'Eevee',0.3,6.5,133,1,'Its genetic code is irregular. It may mutate if it is exposed to radiation from element STONEs.',87.50,12.50,'eevee.png'),(134,'Vaporeon',1,29,134,1,'Lives close to water. Its long tail is ridged with a fin which is often mistaken for a mermaid\'s.',87.50,12.50,'vaporeon.png'),(135,'Jolteon',0.8,24.5,135,1,'It accumulates negative ions in the atmosphere to blast out 10000- volt lightning bolts.',87.50,12.50,'jolteon.png'),(136,'Flareon',0.9,25,136,1,'When storing thermal energy in its body, its temperature could soar to over 1600 degrees.',87.50,12.50,'flareon.png'),(137,'Porygon',0.8,36.5,137,1,'A POKéMON that consists entirely of programming code. Capable of moving freely in cyberspace.',NULL,NULL,'porygon.png'),(138,'Omanyte',0.4,7.5,138,1,'Although long extinct, in rare cases, it can be genetically resurrected from fossils.',87.50,12.50,'omanyte.png'),(139,'Omastar',1,35,139,1,'A prehistoric POKéMON that died out when its heavy shell made it impossible to catch prey.',87.50,12.50,'omastar.png'),(140,'Kabuto',0.5,11.5,140,1,'A POKéMON that was resurrected from a fossil found in what was once the ocean floor eons ago.',87.50,12.50,'kabuto.png'),(141,'Kabutops',1.3,40.5,141,1,'Its sleek shape is perfect for swim­ ming. It slashes prey with its claws and drains the body fluids.',87.50,12.50,'kabutops.png'),(142,'Aerodactyl',1.8,59,142,1,'A ferocious, pre­ historic POKéMON that goes for the enemy\'s throat with its serrated saw-like fangs.',87.50,12.50,'aerodactyl.png'),(143,'Snorlax',2.1,460,143,1,'Very lazy. Just eats and sleeps. As its rotund bulk builds, it becomes steadily more slothful.',87.50,12.50,'snorlax.png'),(144,'Articuno',1.7,55.4,144,1,'A legendary bird POKéMON that is said to appear to doomed people who are lost in icy mountains.',NULL,NULL,'articuno.png'),(145,'Zapdos',1.6,52.6,145,1,'A legendary bird POKéMON that is said to appear from clouds while dropping enormous lightning bolts.',NULL,NULL,'zapdos.png'),(146,'Moltres',2,60,146,1,'Known as the legendary bird of fire. Every flap of its wings creates a dazzling flash of flames.',NULL,NULL,'moltres.png'),(147,'Dratini',1.8,3.3,147,1,'Long considered a mythical POKéMON until recently when a small colony was found living underwater.',50.00,50.00,'dratini.png'),(148,'Dragonair',4,16.5,148,1,'A mystical POKéMON that exudes a gentle aura. Has the ability to change climate conditions.',50.00,50.00,'dragonair.png'),(149,'Dragonite',2.2,210,149,1,'An extremely rarely seen marine POKéMON. Its intelligence is said to match that of humans.',50.00,50.00,'dragonite.png'),(150,'Mewtwo',2,122,150,1,'It was created by a scientist after years of horrific gene splicing and DNA engineering experiments.',NULL,NULL,'mewtwo.png'),(151,'Mew',0.4,4,151,1,'So rare that it is still said to be a mirage by many experts. Only a few people have seen it worldwide.',NULL,NULL,'mew.png');
