  `ability_id` int unsigned NOT NULL,
  `primary_ability` tinyint(1) NOT NULL DEFAULT '1',
  `secondary_ability` tinyint(1) NOT NULL DEFAULT '0',
  `special_ability` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`pokemon_id`,`ability_id`),
  KEY `pokemon_ability_ability_id_foreign` (`ability_id`),
  CONSTRAINT `pokemon_ability_ability_id_foreign` FOREIGN KEY (`ability_id`) REFERENCES `abilities` (`id`),
  CONSTRAINT `pokemon_ability_pokemon_id_foreign` FOREIGN KEY (`pokemon_id`) REFERENCES `pokemon` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
